insert into public.places (
  id, name, address, city, lat, lng, image_url, description, description_ro,
  status, owner_id, created_at
) values
  ('trattoria-nonna-lucia', 'Trattoria Nonna Lucia', 'Str. Covaci, Nr. 97, București', 'București', 44.42825, 26.11165, 'https://images.unsplash.com/photo-1537047902294-62a40c20a6ae', 'Hand-made pasta and slow-cooked sauces, with a short list of Italian wines. Live music on Friday evenings.', 'Paste făcute în casă și sosuri gătite îndelung, cu o listă scurtă de vinuri italienești. Muzică live vineri seara.', 'approved', null, now() - interval '653 days 0 hours'),
  ('sushi-kaze', 'Sushi Kaze', 'Calea Dorobanților, Nr. 12, București', 'București', 44.43405, 26.09454, 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c', 'Japanese rolls, poke bowls and green tea, in a minimalist room.', 'Rulouri japoneze, poke bowls și ceai verde, într-o sală minimalistă.', 'approved', null, now() - interval '534 days 0 hours'),
  ('ramen-koen', 'Ramen Koen', 'Str. Popa Nan, Nr. 44, București', 'București', 44.42005, 26.11278, 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624', 'Steaming noodle soups and spicy bowls, quick and filling after work.', 'Supe aburinde cu tăiței și boluri picante, rapide și sățioase după program.', 'approved', null, now() - interval '610 days 0 hours'),
  ('cafeneaua-artistilor', 'Cafeneaua Artiștilor', 'Str. Lipscani, Nr. 31, București', 'București', 44.42313, 26.10841, 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb', 'Espresso, filter coffee and home-made cakes, served by baristas who know their beans.', 'Espresso, cafea la filtru și prăjituri de casă, servite de bariști care își cunosc boabele.', 'approved', null, now() - interval '493 days 0 hours'),
  ('la-mici-si-bere', 'La Mici și Bere', 'Str. Franceză, Nr. 85, București', 'București', 44.42287, 26.09458, 'https://images.unsplash.com/photo-1529042410759-befb1204b468', 'Romanian food like at grandma’s: sour soups, sarmale with polenta and papanași. A quiet terrace in summer.', 'Mâncare românească ca la bunica: ciorbe, sarmale cu mămăligă și papanași. O terasă liniștită vara.', 'approved', null, now() - interval '430 days 0 hours'),
  ('taverna-olimpia', 'Taverna Olimpia', 'Calea Floreasca, Nr. 93, București', 'București', 44.42646, 26.09686, 'https://images.unsplash.com/photo-1540189549336-e6e99c3679fe', 'A Greek taverna with gyros, grilled octopus and a big Greek salad.', 'O tavernă grecească cu gyros, caracatiță la grătar și salată grecească mare.', 'approved', null, now() - interval '224 days 0 hours'),
  ('green-spoon', 'Green Spoon', 'Bd. Dacia, Nr. 6, București', 'București', 44.42052, 26.11336, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c', 'Colourful vegan food made from local vegetables, and cold-pressed juices. Pets are welcome.', 'Mâncare vegană colorată din legume locale și sucuri presate la rece. Animalele de companie sunt binevenite.', 'approved', (select id from public.profiles where email = 'operator@test.ro'), now() - interval '566 days 0 hours'),
  ('brunch-co', 'Brunch & Co', 'Calea Victoriei, Nr. 69, București', 'București', 44.42084, 26.10393, 'https://images.unsplash.com/photo-1528207776546-365bb710ee93', 'All-day brunch: eggs Benedict, fluffy pancakes and fresh orange juice. Pets are welcome.', 'Brunch toată ziua: ouă Benedict, clătite pufoase și suc proaspăt de portocale. Animalele de companie sunt binevenite.', 'approved', null, now() - interval '555 days 0 hours'),
  ('the-cellar-wine-bar', 'The Cellar Wine Bar', 'Str. Smârdan, Nr. 93, București', 'București', 44.4294, 26.10743, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3', 'A wine bar with over 200 Romanian labels, cheese boards and wine tastings. Live music on Friday evenings.', 'Un wine bar cu peste 200 de etichete românești, platouri cu brânzeturi și degustări. Muzică live vineri seara.', 'approved', null, now() - interval '658 days 0 hours'),
  ('roastery-somes', 'Roastery Someș', 'Str. Memorandumului, Nr. 55, Cluj-Napoca', 'Cluj-Napoca', 46.77694, 23.62459, 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb', 'Specialty coffee roasted in small batches, with a calm room for reading or work.', 'Cafea de specialitate prăjită în loturi mici, într-o sală liniștită pentru citit sau lucru.', 'approved', null, now() - interval '41 days 0 hours'),
  ('casa-cu-gradina', 'Casa cu Grădină', 'Str. Napoca, Nr. 58, Cluj-Napoca', 'Cluj-Napoca', 46.77123, 23.61186, 'https://images.unsplash.com/photo-1529042410759-befb1204b468', 'Romanian food like at grandma’s: sour soups, sarmale with polenta and papanași. Good Wi-Fi and plugs at every table.', 'Mâncare românească ca la bunica: ciorbe, sarmale cu mămăligă și papanași. Wi-Fi bun și prize la fiecare masă.', 'approved', null, now() - interval '270 days 0 hours'),
  ('forno-vecchio', 'Forno Vecchio', 'Piața Muzeului, Nr. 10, Cluj-Napoca', 'Cluj-Napoca', 46.77425, 23.62377, 'https://images.unsplash.com/photo-1458642849426-cfb724f15ef7', 'Neapolitan pizza from a wood-fired oven, with a thin base and puffy crust.', 'Pizza napoletană la cuptor cu lemne, cu blat subțire și margini pufoase.', 'approved', null, now() - interval '341 days 0 hours'),
  ('taco-loco', 'Taco Loco', 'Str. Iuliu Maniu, Nr. 63, Cluj-Napoca', 'Cluj-Napoca', 46.77459, 23.63207, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836', 'Tacos, burritos and fresh guacamole, with Mexican music and margaritas. A quiet terrace in summer.', 'Tacos, burritos și guacamole proaspăt, cu muzică mexicană și margarita. O terasă liniștită vara.', 'approved', (select id from public.profiles where email = 'operator@test.ro'), now() - interval '272 days 0 hours'),
  ('ceainaria-sub-tei', 'Ceainăria Sub Tei', 'Str. Eroilor, Nr. 63, Cluj-Napoca', 'Cluj-Napoca', 46.76516, 23.6121, 'https://images.unsplash.com/photo-1445116572660-236099ec97a0', 'Over forty teas from all over the world, served slowly, in a quiet room with cushions.', 'Peste patruzeci de ceaiuri din toată lumea, servite fără grabă, într-o cameră liniștită cu perne.', 'approved', null, now() - interval '505 days 0 hours'),
  ('burger-factory', 'Burger Factory', 'Bd. 21 Decembrie 1989, Nr. 43, Cluj-Napoca', 'Cluj-Napoca', 46.76906, 23.61687, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd', 'Juicy burgers in brioche buns, with a vegetarian one on every menu. A corner for children.', 'Burgeri suculenți în chifle brioșă, cu unul vegetarian în fiecare meniu. Un colț pentru copii.', 'approved', null, now() - interval '462 days 0 hours'),
  ('bistro-botanic', 'Bistro Botanic', 'Str. Republicii, Nr. 43, Cluj-Napoca', 'Cluj-Napoca', 46.77815, 23.62451, 'https://images.unsplash.com/photo-1533777857889-4be7c70b33f7', 'A modern bistro with a menu that changes with the seasons and a good wine list. A quiet terrace in summer.', 'Un bistro modern, cu un meniu care se schimbă după anotimp și o listă bună de vinuri. O terasă liniștită vara.', 'approved', null, now() - interval '704 days 0 hours'),
  ('bastion-craft-beer', 'Bastion Craft Beer', 'Str. Hector, Nr. 18, Timișoara', 'Timișoara', 45.75311, 21.19829, 'https://images.unsplash.com/photo-1514933651103-005eec06c04b', 'A cosy pub with local beers, burgers and concerts at the weekend. Open until late.', 'Un pub primitor, cu beri locale, burgeri și concerte în weekend. Deschis până târziu.', 'approved', null, now() - interval '529 days 0 hours'),
  ('pho-saigon', 'Pho Saigon', 'Str. Alba Iulia, Nr. 26, Timișoara', 'Timișoara', 45.74448, 21.2137, 'https://images.unsplash.com/photo-1585032226651-759b368d7246', 'Pho with fresh herbs, crispy spring rolls and Vietnamese iced coffee.', 'Pho cu ierburi proaspete, rulouri de primăvară crocante și cafea vietnameză cu gheață.', 'approved', null, now() - interval '123 days 0 hours'),
