  ('gelateria-bega', 'Gelateria Bega', 'Splaiul Tudor Vladimirescu, Nr. 112, Timișoara', 'Timișoara', 45.74516, 21.20177, 'https://images.unsplash.com/photo-1484723091739-30a097e8f929', 'A pastry shop with French cakes, macarons and hot chocolate. A quiet terrace in summer.', 'O cofetărie cu prăjituri franțuzești, macarons și ciocolată caldă. O terasă liniștită vara.', 'approved', null, now() - interval '450 days 0 hours'),
  ('steakhouse-unirii', 'Steakhouse Unirii', 'Piața Unirii, Nr. 94, Timișoara', 'Timișoara', 45.74413, 21.20378, 'https://images.unsplash.com/photo-1544025162-d76694265947', 'A grill house with ribs, steaks and a big terrace for summer evenings. Good Wi-Fi and plugs at every table.', 'Un grill cu coaste, fripturi și o terasă mare pentru serile de vară. Wi-Fi bun și prize la fiecare masă.', 'approved', null, now() - interval '351 days 0 hours'),
  ('cafe-mercy', 'Café Mercy', 'Str. Mercy, Nr. 78, Timișoara', 'Timișoara', 45.74712, 21.19803, 'https://images.unsplash.com/photo-1498804103079-a6351b050096', 'Specialty coffee roasted in small batches, with a calm room for reading or work.', 'Cafea de specialitate prăjită în loturi mici, într-o sală liniștită pentru citit sau lucru.', 'approved', (select id from public.profiles where email = 'operator@test.ro'), now() - interval '118 days 0 hours'),
